mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  float r = length(p);
  float a = atan(p.y, p.x);
  float ang = time * 6.0;
  float beam1 = abs(sin(a - ang)) - 0.04;
  float beam2 = abs(sin(a - ang + 3.1415)) - 0.04;
  float beam = min(beam1, beam2);
  vec3 col = vec3(0.01, 0.03, 0.06);
  col += vec3(0.2, 0.85, 1.3) * (0.015 / (0.02 + abs(beam))) * smoothstep(1.8, 0.2, r);
  float star = 0.025 / (0.01 + r * r);
  col += star * vec3(0.9, 0.95, 1.0) * (1.0 + 0.5 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
